const config = {
  "previewFeatures": [],
  "clientVersion": "7.4.1",
  "engineVersion": "55ae170b1ced7fc6ed07a15f110549408c501bb3",
  "activeProvider": "postgresql",
  "inlineSchema": "// ================================================================\n// LearnHub — Per-Tenant Database Schema\n// Each tenant (institute) gets its own database with this schema.\n// Contains all educational data: users, courses, exams, fees, etc.\n// ================================================================\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../../backend/generated/tenant\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ================================================================\n// USER MANAGEMENT\n// ================================================================\n\n/// Users within a tenant — can be Admin, Teacher, Student, or Parent\nmodel User {\n  id           String     @id @default(uuid()) @db.Uuid\n  email        String     @unique @db.VarChar(255)\n  passwordHash String     @map(\"password_hash\") @db.Text\n  firstName    String     @map(\"first_name\") @db.VarChar(100)\n  lastName     String     @map(\"last_name\") @db.VarChar(100)\n  phone        String?    @db.VarChar(20)\n  nic          String?    @db.VarChar(20)\n  role         UserRole\n  status       UserStatus @default(ACTIVE)\n  avatarUrl    String?    @map(\"avatar_url\") @db.Text\n  createdAt    DateTime   @default(now()) @map(\"created_at\")\n  updatedAt    DateTime   @updatedAt @map(\"updated_at\")\n\n  // Relations\n  batchEnrollments          BatchEnrollment[]\n  batchTeachers             BatchTeacher[]\n  submissions               Submission[]\n  attendanceRecords         AttendanceRecord[]\n  examAttempts              ExamAttempt[]\n  manualResults             ManualResult[]      @relation(\"StudentResults\")\n  enteredResults            ManualResult[]      @relation(\"EnteredByTeacher\")\n  feeInvoices               FeeInvoice[]\n  notifications             Notification[]\n  certificates              Certificate[]\n  auditLogs                 AuditLog[]\n  parentLinks               ParentStudentLink[] @relation(\"StudentLink\")\n  childLinks                ParentStudentLink[] @relation(\"ParentLink\")\n  createdAssignments        Assignment[]\n  createdAttendanceSessions AttendanceSession[]\n  createdAnnouncements      Announcement[]\n  gradedSubmissions         Submission[]        @relation(\"GradedByTeacher\")\n\n  @@map(\"users\")\n}\n\nenum UserRole {\n  ADMIN\n  TEACHER\n  STUDENT\n  PARENT\n}\n\nenum UserStatus {\n  ACTIVE\n  INACTIVE\n  SUSPENDED\n}\n\n// ================================================================\n// COURSES & BATCHES\n// ================================================================\n\n/// A course offered by the institute (e.g. \"Mathematics Grade 11\")\nmodel Course {\n  id            String       @id @default(uuid()) @db.Uuid\n  title         String       @db.VarChar(255)\n  description   String?      @db.Text\n  code          String?      @unique @db.VarChar(50)\n  coverImageUrl String?      @map(\"cover_image_url\") @db.Text\n  status        CourseStatus @default(ACTIVE)\n  createdAt     DateTime     @default(now()) @map(\"created_at\")\n  updatedAt     DateTime     @updatedAt @map(\"updated_at\")\n\n  batches      Batch[]\n  contentItems ContentItem[]\n  certificates Certificate[]\n\n  @@map(\"courses\")\n}\n\nenum CourseStatus {\n  ACTIVE\n  ARCHIVED\n  DRAFT\n}\n\n/// A batch is a specific class section within a course (e.g. \"2025 Jan Batch\")\nmodel Batch {\n  id        String      @id @default(uuid()) @db.Uuid\n  courseId  String      @map(\"course_id\") @db.Uuid\n  name      String      @db.VarChar(255)\n  startDate DateTime?   @map(\"start_date\") @db.Date\n  endDate   DateTime?   @map(\"end_date\") @db.Date\n  capacity  Int?\n  status    BatchStatus @default(ACTIVE)\n  createdAt DateTime    @default(now()) @map(\"created_at\")\n  updatedAt DateTime    @updatedAt @map(\"updated_at\")\n\n  course             Course              @relation(fields: [courseId], references: [id], onDelete: Cascade)\n  enrollments        BatchEnrollment[]\n  teachers           BatchTeacher[]\n  timetableSlots     TimetableSlot[]\n  contentItems       ContentItem[]\n  assignments        Assignment[]\n  attendanceSessions AttendanceSession[]\n  exams              Exam[]\n  feeInvoices        FeeInvoice[]\n  certificates       Certificate[]\n  announcements      Announcement[]\n\n  @@map(\"batches\")\n}\n\nenum BatchStatus {\n  ACTIVE\n  COMPLETED\n  CANCELLED\n}\n\n// ================================================================\n// ENROLLMENTS & ASSIGNMENTS\n// ================================================================\n\n/// Links students to batches — tracks enrollment status and fee status\nmodel BatchEnrollment {\n  id         String           @id @default(uuid()) @db.Uuid\n  batchId    String           @map(\"batch_id\") @db.Uuid\n  studentId  String           @map(\"student_id\") @db.Uuid\n  enrolledAt DateTime         @default(now()) @map(\"enrolled_at\")\n  status     EnrollmentStatus @default(ACTIVE)\n  feeStatus  FeeStatus        @default(PENDING) @map(\"fee_status\")\n\n  batch   Batch @relation(fields: [batchId], references: [id], onDelete: Cascade)\n  student User  @relation(fields: [studentId], references: [id], onDelete: Cascade)\n\n  @@unique([batchId, studentId])\n  @@map(\"batch_enrollments\")\n}\n\nenum EnrollmentStatus {\n  ACTIVE\n  DROPPED\n  COMPLETED\n}\n\nenum FeeStatus {\n  PENDING\n  PAID\n  OVERDUE\n  WAIVED\n}\n\n/// Links teachers to batches\nmodel BatchTeacher {\n  id         String   @id @default(uuid()) @db.Uuid\n  batchId    String   @map(\"batch_id\") @db.Uuid\n  teacherId  String   @map(\"teacher_id\") @db.Uuid\n  assignedAt DateTime @default(now()) @map(\"assigned_at\")\n\n  batch   Batch @relation(fields: [batchId], references: [id], onDelete: Cascade)\n  teacher User  @relation(fields: [teacherId], references: [id], onDelete: Cascade)\n\n  @@unique([batchId, teacherId])\n  @@map(\"batch_teachers\")\n}\n\n// ================================================================\n// TIMETABLE\n// ================================================================\n\n/// Recurring weekly schedule for a batch\nmodel TimetableSlot {\n  id        String  @id @default(uuid()) @db.Uuid\n  batchId   String  @map(\"batch_id\") @db.Uuid\n  dayOfWeek Int     @map(\"day_of_week\") // 0=Sunday, 6=Saturday\n  startTime String  @map(\"start_time\") @db.VarChar(5) // \"HH:mm\"\n  endTime   String  @map(\"end_time\") @db.VarChar(5) // \"HH:mm\"\n  room      String? @db.VarChar(100)\n  meetLink  String? @map(\"meet_link\") @db.Text\n\n  batch              Batch               @relation(fields: [batchId], references: [id], onDelete: Cascade)\n  attendanceSessions AttendanceSession[]\n\n  @@map(\"timetable_slots\")\n}\n\n// ================================================================\n// CONTENT MANAGEMENT\n// ================================================================\n\n/// Learning materials attached to courses/batches\nmodel ContentItem {\n  id           String      @id @default(uuid()) @db.Uuid\n  courseId     String      @map(\"course_id\") @db.Uuid\n  batchId      String?     @map(\"batch_id\") @db.Uuid\n  title        String      @db.VarChar(255)\n  type         ContentType\n  url          String?     @db.Text\n  bunnyVideoId String?     @map(\"bunny_video_id\") @db.VarChar(100)\n  orderIndex   Int         @default(0) @map(\"order_index\")\n  isVisible    Boolean     @default(true) @map(\"is_visible\")\n  createdAt    DateTime    @default(now()) @map(\"created_at\")\n  updatedAt    DateTime    @updatedAt @map(\"updated_at\")\n\n  course Course @relation(fields: [courseId], references: [id], onDelete: Cascade)\n  batch  Batch? @relation(fields: [batchId], references: [id], onDelete: SetNull)\n\n  @@map(\"content_items\")\n}\n\nenum ContentType {\n  VIDEO\n  PDF\n  DOCUMENT\n  LINK\n}\n\n// ================================================================\n// ASSIGNMENTS & SUBMISSIONS\n// ================================================================\n\n/// An assignment created by a teacher for a batch\nmodel Assignment {\n  id          String    @id @default(uuid()) @db.Uuid\n  batchId     String    @map(\"batch_id\") @db.Uuid\n  title       String    @db.VarChar(255)\n  description String?   @db.Text\n  dueDate     DateTime? @map(\"due_date\")\n  maxMarks    Int       @map(\"max_marks\")\n  createdBy   String    @map(\"created_by\") @db.Uuid\n  createdAt   DateTime  @default(now()) @map(\"created_at\")\n  updatedAt   DateTime  @updatedAt @map(\"updated_at\")\n\n  batch       Batch        @relation(fields: [batchId], references: [id], onDelete: Cascade)\n  creator     User         @relation(fields: [createdBy], references: [id])\n  submissions Submission[]\n\n  @@map(\"assignments\")\n}\n\n/// A student's submission for an assignment\nmodel Submission {\n  id           String   @id @default(uuid()) @db.Uuid\n  assignmentId String   @map(\"assignment_id\") @db.Uuid\n  studentId    String   @map(\"student_id\") @db.Uuid\n  fileUrl      String?  @map(\"file_url\") @db.Text\n  submittedAt  DateTime @default(now()) @map(\"submitted_at\")\n  marks        Int?\n  feedback     String?  @db.Text\n  gradedBy     String?  @map(\"graded_by\") @db.Uuid\n\n  assignment Assignment @relation(fields: [assignmentId], references: [id], onDelete: Cascade)\n  student    User       @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  grader     User?      @relation(\"GradedByTeacher\", fields: [gradedBy], references: [id])\n\n  @@unique([assignmentId, studentId])\n  @@map(\"submissions\")\n}\n\n// ================================================================\n// ATTENDANCE\n// ================================================================\n\n/// An attendance session for a specific date and timetable slot\nmodel AttendanceSession {\n  id              String   @id @default(uuid()) @db.Uuid\n  batchId         String   @map(\"batch_id\") @db.Uuid\n  timetableSlotId String?  @map(\"timetable_slot_id\") @db.Uuid\n  date            DateTime @db.Date\n  createdBy       String   @map(\"created_by\") @db.Uuid\n  createdAt       DateTime @default(now()) @map(\"created_at\")\n\n  batch         Batch              @relation(fields: [batchId], references: [id], onDelete: Cascade)\n  timetableSlot TimetableSlot?     @relation(fields: [timetableSlotId], references: [id])\n  creator       User               @relation(fields: [createdBy], references: [id])\n  records       AttendanceRecord[]\n\n  @@map(\"attendance_sessions\")\n}\n\n/// Individual attendance record per student per session\nmodel AttendanceRecord {\n  id        String           @id @default(uuid()) @db.Uuid\n  sessionId String           @map(\"session_id\") @db.Uuid\n  studentId String           @map(\"student_id\") @db.Uuid\n  status    AttendanceStatus\n\n  session AttendanceSession @relation(fields: [sessionId], references: [id], onDelete: Cascade)\n  student User              @relation(fields: [studentId], references: [id], onDelete: Cascade)\n\n  @@unique([sessionId, studentId])\n  @@map(\"attendance_records\")\n}\n\nenum AttendanceStatus {\n  PRESENT\n  ABSENT\n  LATE\n  EXCUSED\n}\n\n// ================================================================\n// EXAMS & RESULTS\n// ================================================================\n\n/// An exam (can be online MCQ or manually graded)\nmodel Exam {\n  id              String     @id @default(uuid()) @db.Uuid\n  batchId         String     @map(\"batch_id\") @db.Uuid\n  title           String     @db.VarChar(255)\n  type            ExamType\n  date            DateTime?  @db.Date\n  durationMinutes Int?       @map(\"duration_minutes\")\n  maxMarks        Int        @map(\"max_marks\")\n  status          ExamStatus @default(DRAFT)\n  createdAt       DateTime   @default(now()) @map(\"created_at\")\n  updatedAt       DateTime   @updatedAt @map(\"updated_at\")\n\n  batch         Batch          @relation(fields: [batchId], references: [id], onDelete: Cascade)\n  questions     ExamQuestion[]\n  attempts      ExamAttempt[]\n  manualResults ManualResult[]\n\n  @@map(\"exams\")\n}\n\nenum ExamType {\n  ONLINE_MCQ\n  MANUAL\n}\n\nenum ExamStatus {\n  DRAFT\n  PUBLISHED\n  IN_PROGRESS\n  COMPLETED\n}\n\n/// MCQ question for an online exam\nmodel ExamQuestion {\n  id            String @id @default(uuid()) @db.Uuid\n  examId        String @map(\"exam_id\") @db.Uuid\n  questionText  String @map(\"question_text\") @db.Text\n  optionA       String @map(\"option_a\") @db.Text\n  optionB       String @map(\"option_b\") @db.Text\n  optionC       String @map(\"option_c\") @db.Text\n  optionD       String @map(\"option_d\") @db.Text\n  correctOption String @map(\"correct_option\") @db.VarChar(1) // A, B, C, or D\n  marks         Int    @default(1)\n\n  exam    Exam         @relation(fields: [examId], references: [id], onDelete: Cascade)\n  answers ExamAnswer[]\n\n  @@map(\"exam_questions\")\n}\n\n/// A student's attempt at an online exam\nmodel ExamAttempt {\n  id          String    @id @default(uuid()) @db.Uuid\n  examId      String    @map(\"exam_id\") @db.Uuid\n  studentId   String    @map(\"student_id\") @db.Uuid\n  startedAt   DateTime  @default(now()) @map(\"started_at\")\n  submittedAt DateTime? @map(\"submitted_at\")\n  totalMarks  Int?      @map(\"total_marks\")\n  percentage  Decimal?  @db.Decimal(5, 2)\n\n  exam    Exam         @relation(fields: [examId], references: [id], onDelete: Cascade)\n  student User         @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  answers ExamAnswer[]\n\n  @@unique([examId, studentId])\n  @@map(\"exam_attempts\")\n}\n\n/// Individual answer for each question in an attempt\nmodel ExamAnswer {\n  id             String  @id @default(uuid()) @db.Uuid\n  attemptId      String  @map(\"attempt_id\") @db.Uuid\n  questionId     String  @map(\"question_id\") @db.Uuid\n  selectedOption String? @map(\"selected_option\") @db.VarChar(1)\n  isCorrect      Boolean @default(false) @map(\"is_correct\")\n\n  attempt  ExamAttempt  @relation(fields: [attemptId], references: [id], onDelete: Cascade)\n  question ExamQuestion @relation(fields: [questionId], references: [id], onDelete: Cascade)\n\n  @@unique([attemptId, questionId])\n  @@map(\"exam_answers\")\n}\n\n/// Manually entered results (for non-MCQ exams)\nmodel ManualResult {\n  id            String  @id @default(uuid()) @db.Uuid\n  examId        String  @map(\"exam_id\") @db.Uuid\n  studentId     String  @map(\"student_id\") @db.Uuid\n  marksObtained Int     @map(\"marks_obtained\")\n  remarks       String? @db.Text\n  enteredBy     String  @map(\"entered_by\") @db.Uuid\n\n  exam      Exam     @relation(fields: [examId], references: [id], onDelete: Cascade)\n  student   User     @relation(\"StudentResults\", fields: [studentId], references: [id], onDelete: Cascade)\n  teacher   User     @relation(\"EnteredByTeacher\", fields: [enteredBy], references: [id])\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  @@unique([examId, studentId])\n  @@map(\"manual_results\")\n}\n\n// ================================================================\n// FEE MANAGEMENT\n// ================================================================\n\n/// Fee invoice for a student in a batch\nmodel FeeInvoice {\n  id               String        @id @default(uuid()) @db.Uuid\n  studentId        String        @map(\"student_id\") @db.Uuid\n  batchId          String        @map(\"batch_id\") @db.Uuid\n  amountLkr        Decimal       @map(\"amount_lkr\") @db.Decimal(10, 2)\n  dueDate          DateTime      @map(\"due_date\") @db.Date\n  status           InvoiceStatus @default(PENDING)\n  paymentMethod    String?       @map(\"payment_method\") @db.VarChar(50)\n  paidAt           DateTime?     @map(\"paid_at\")\n  payherePaymentId String?       @map(\"payhere_payment_id\") @db.VarChar(255)\n  createdAt        DateTime      @default(now()) @map(\"created_at\")\n  updatedAt        DateTime      @updatedAt @map(\"updated_at\")\n\n  student User  @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  batch   Batch @relation(fields: [batchId], references: [id], onDelete: Cascade)\n\n  @@map(\"fee_invoices\")\n}\n\nenum InvoiceStatus {\n  PENDING\n  PAID\n  OVERDUE\n  CANCELLED\n  REFUNDED\n}\n\n// ================================================================\n// ANNOUNCEMENTS & NOTIFICATIONS\n// ================================================================\n\n/// Announcements targeted to specific groups\nmodel Announcement {\n  id         String             @id @default(uuid()) @db.Uuid\n  targetType AnnouncementTarget @map(\"target_type\")\n  targetId   String?            @map(\"target_id\") @db.Uuid\n  title      String             @db.VarChar(255)\n  body       String             @db.Text\n  createdBy  String             @map(\"created_by\") @db.Uuid\n  createdAt  DateTime           @default(now()) @map(\"created_at\")\n\n  creator User   @relation(fields: [createdBy], references: [id])\n  batch   Batch? @relation(fields: [targetId], references: [id])\n\n  @@map(\"announcements\")\n}\n\nenum AnnouncementTarget {\n  ALL\n  BATCH\n  ROLE\n}\n\n/// Per-user notifications\nmodel Notification {\n  id        String   @id @default(uuid()) @db.Uuid\n  userId    String   @map(\"user_id\") @db.Uuid\n  type      String   @db.VarChar(50)\n  title     String   @db.VarChar(255)\n  body      String   @db.Text\n  isRead    Boolean  @default(false) @map(\"is_read\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@map(\"notifications\")\n}\n\n// ================================================================\n// PARENT-STUDENT LINKS\n// ================================================================\n\n/// Associates parent users with their children (student users)\nmodel ParentStudentLink {\n  id        String @id @default(uuid()) @db.Uuid\n  parentId  String @map(\"parent_id\") @db.Uuid\n  studentId String @map(\"student_id\") @db.Uuid\n\n  parent  User @relation(\"ParentLink\", fields: [parentId], references: [id], onDelete: Cascade)\n  student User @relation(\"StudentLink\", fields: [studentId], references: [id], onDelete: Cascade)\n\n  @@unique([parentId, studentId])\n  @@map(\"parent_student_links\")\n}\n\n// ================================================================\n// CERTIFICATES\n// ================================================================\n\n/// Issued completion certificates\nmodel Certificate {\n  id             String   @id @default(uuid()) @db.Uuid\n  studentId      String   @map(\"student_id\") @db.Uuid\n  courseId       String   @map(\"course_id\") @db.Uuid\n  batchId        String?  @map(\"batch_id\") @db.Uuid\n  issuedAt       DateTime @default(now()) @map(\"issued_at\")\n  certificateUrl String?  @map(\"certificate_url\") @db.Text\n  uniqueCode     String   @unique @map(\"unique_code\") @db.VarChar(50)\n\n  student User   @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  course  Course @relation(fields: [courseId], references: [id])\n  batch   Batch? @relation(fields: [batchId], references: [id])\n\n  @@map(\"certificates\")\n}\n\n// ================================================================\n// AUDIT LOGGING\n// ================================================================\n\n/// Immutable audit trail for sensitive operations\nmodel AuditLog {\n  id           String   @id @default(uuid()) @db.Uuid\n  userId       String?  @map(\"user_id\") @db.Uuid\n  action       String   @db.VarChar(50) // CREATE, UPDATE, DELETE\n  entityType   String   @map(\"entity_type\") @db.VarChar(100)\n  entityId     String   @map(\"entity_id\") @db.Uuid\n  oldValueJson Json?    @map(\"old_value_json\")\n  newValueJson Json?    @map(\"new_value_json\")\n  ipAddress    String?  @map(\"ip_address\") @db.VarChar(45)\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n\n  user User? @relation(fields: [userId], references: [id], onDelete: SetNull)\n\n  @@index([entityType, entityId])\n  @@index([userId])\n  @@index([createdAt])\n  @@map(\"audit_logs\")\n}\n"
}

